add_action( 'woocommerce_admin_order_data_after_billing_address', 'perfectpixel_edit_order_custom_field' );
add_action( 'woocommerce_process_shop_order_meta', 'perfectpixel_save_order_custom_field', 50 );

function perfectpixel_edit_order_custom_field( $order ) {
	$key = sanitize_key( '{{order_field_key}}' );
	woocommerce_wp_text_input(
		array(
			'id'            => 'perfectpixel_order_field',
			'label'         => '{{order_field_label}}:',
			'value'         => $order->get_meta( $key ),
			'wrapper_class' => 'form-field-wide',
		)
	);
}

function perfectpixel_save_order_custom_field( $order_id ) {
	if ( ! isset( $_POST['perfectpixel_order_field'] ) || ! current_user_can( 'edit_shop_orders' ) ) {
		return;
	}
	$order = wc_get_order( $order_id );
	if ( $order ) {
		$order->update_meta_data( sanitize_key( '{{order_field_key}}' ), sanitize_text_field( wp_unslash( $_POST['perfectpixel_order_field'] ) ) );
		$order->save();
	}
}
